function randomString(length: number): string {
  const characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  let result = "";
  for (let i = 0; i < length; i++) {
    result += characters.charAt(Math.floor(Math.random() * characters.length));
  }
  return result;
}

function randomPick(options: any[]): any {
  return options[Math.floor(Math.random() * options.length)];
}

function makeData(count: number, factory: object | (() => any)): any[] {
  return Array.from({ length: count }, () => {
    // clone non primitive data
    if (typeof factory === "object") return { ...factory };
    if (typeof factory === "function") return factory();
    throw new Error("Invalid factory");
  });
}

function formatNumber(val: number): string {
  if (val >= 1e12) {
    return `${toFixed(val / 1e12)}T`;
  }
  if (val >= 1e9) {
    return `${toFixed(val / 1e9)}B`;
  }
  if (val >= 1e6) {
    return `${toFixed(val / 1e6)}M`;
  }
  if (val >= 1e3) {
    return `${toFixed(val / 1e3)}k`;
  }
  if (val >= 1) {
    return val.toString();
  }
  if (val >= 1e-3) {
    return `${toFixed(val * 1e3)}m`;
  }
  if (val >= 1e-6) {
    return `${toFixed(val * 1e6)}µ`;
  }
  if (val >= 1e-9) {
    return `${toFixed(val * 1e9)}n`;
  }
  if (val >= 1e-12) {
    return `${toFixed(val * 1e12)}p`;
  }
  return val.toString();
}

function toFixed(val: number) {
  return val.toPrecision(3);
}

function makeSchema(z: typeof z4) {
  const z4fields = {
    data1: z.string(),
    data2: z.string(),
    data3: z.string(),
    // data4: z.string(),
    // data5: z.string(),
    // data6: z.string(),
    // data7: z.string(),
    // data8: z.string(),
    // data9: z.string(),
    // data10: z.string(),
  };
  const z4Union = z.union([
    z.object({
      type: z.literal("a"),
      ...z4fields,
    }),
    z.object({
      type: z.literal("b"),
      ...z4fields,
    }),
    z.object({
      type: z.literal("c"),
      ...z4fields,
    }),
    z.object({
      type: z.literal("d"),
      ...z4fields,
    }),
    z.object({
      type: z.literal("e"),
      ...z4fields,
    }),
    z.object({
      type: z.literal("f"),
      ...z4fields,
    }),
    z.object({
      type: z.literal("g"),
      ...z4fields,
    }),
  ]);
  return z4Union;
}

