function lazyWithInternalProp<T>(getter: () => T) {
  return {
    __value: undefined as T,
    get value() {
      if (this.__value) return this.__value;
      const value = getter();
      this.__value = value;
      return value;
    },
  };
}

function lazyWithScopeProp<T>(getter: () => T): {
  value: T;
  __value?: T;
} {
  let __value: T;
  return {
    get value() {
      if (__value) return __value;
      const value = getter();
      __value = value;
      return value;
    },
  };
}

function lazyWithGetterOverride<T>(getter: () => T): {
  value: T;
} {
  return {
    get value() {
      const value = getter();
      Object.defineProperty(this, "value", { value });
      return value;
    },
  };
}

function metabench<D>(name: string, benchmarks?: Benchmarks<D>): Metabench {
  let bench: Metabench;
  if (BENCH === "tinybench") {
    bench = new Tinybench(name, benchmarks || {});
  } else if (BENCH === "benchmarkjs") {
    bench = new BenchmarkJS(name, benchmarks || {});
  } else if (BENCH === "mitata") {
    bench = new Mitata(name, benchmarks || {});
  } else {
    throw new Error(`Unknown benchmark runner: ${BENCH}`);
  }
  // console.log(`running benchmark with ${BENCH}...`);
  return bench;
}

function benchWithData<D>(params: BenchWithDataParams<D> & ThisType<{ data: D }>): Metabench<D> {
  const bench = metabench(params.name);
  // console.log(`Batch size: ${params.batch}`);

  if (params.batch === null) {
    const DATA = params.data();
    for (const key in params.benchmarks) {
      const _bench = params.benchmarks[key].bind({
        data: DATA,
      }) as any;
      bench.add(key, _bench);
    }
  } else {
    const DATA = Array.from({ length: params.batch || 1000 }, params.data);
    for (const key in params.benchmarks) {
      const _bench = params.benchmarks[key].bind({
        data: DATA,
      }) as any;
      bench.add(key, () => {
        for (const d of DATA) {
          _bench(d);
        }
      });
    }
  }

  return bench;
}

